describe("CustomAlerts", function () {
    this.timeout(0);
    this.fixture = "Piwik\\Plugins\\CustomAlerts\\tests\\Fixtures\\CustomAlerts";

    var generalParams = 'idSite=1&period=year&date=2012-08-09';

    async function screenshotPageWrap() {
        const pageWrap = await page.$('.pageWrap');
        const screenshot = await pageWrap.screenshot();
        return screenshot;
    }

    // The list renders at the page level and is taller than the page wrap, so naming it here as
    // well made the captured height depend on whether the browser had re-laid the list out by the
    // time the harness measured it - the same image came out 1843px or 1965px tall from one run to
    // the next. The page wrap alone is stable, and the part of the list that overlaps it is the
    // same either way; that the right reports are listed is asserted against the DOM below.
    async function screenshotPageWrapWithOpenList() {
        return page.screenshotSelector('.pageWrap');
    }

    // Opening the list and expanding a category is what a user does; forcing .secondLevel visible
    // skipped the control entirely and left that path untested.
    async function openReportCategory(category) {
        await page.click('.expandableSelector .select-wrapper');
        await page.waitForFunction(
            '$(".expandableList:visible").length > 0',
        );

        // the list keeps the category it last expanded, so clicking that one again would collapse it
        await page.evaluate(function (cat) {
            var $category = $('.expandableList:visible h4')
                .filter(function () { return $(this).text().trim().indexOf(cat) !== -1; });

            if (!$category.closest('li').find('.secondLevel').is(':visible')) {
                $category.click();
            }
        }, category);

        // waiting on the category itself, so a click that misses fails here rather than silently
        await page.waitForFunction(function (cat) {
            var $category = window.$('.expandableList:visible h4')
                .filter(function () { return window.$(this).text().trim().indexOf(cat) !== -1; });

            return $category.closest('li').find('.secondLevel').is(':visible');
        }, {}, category);
    }

    it('should load the triggered custom alerts list correctly', async function () {
        await page.goto("?" + generalParams + "&module=CustomAlerts&action=historyTriggeredAlerts&idSite=1&period=day&date=yesterday");
        expect(await screenshotPageWrap()).to.matchImage('list_triggered');
    });

    it('should load the custom alerts list correctly', async function () {
        await page.goto("?" + generalParams + "&module=CustomAlerts&action=index&idSite=1&period=day&date=yesterday");
        expect(await screenshotPageWrap()).to.matchImage('list');
    });

    it('should load custom alerts edit screen', async function () {
        await page.click('tbody tr:first-child td.edit a');
        await page.waitForNetworkIdle();
        await page.waitForTimeout(350); // wait for animation
        expect(await screenshotPageWrap()).to.matchImage('edit');
    });

    it('should show the report mediums', async function () {
        await page.click('.report-mediums .select-dropdown');
        await page.waitForNetworkIdle();
        await page.waitForTimeout(350); // wait for animation
        expect(await screenshotPageWrap()).to.matchImage('report_mediums');
        await page.click('.report-mediums .select-dropdown');
    });

    it('should reload alert conditions when site is changed', async function () {
        await page.evaluate(function() {
            $('.siteSelector .piwikSelector__dropdown li:contains("Piwik test"):last').click();
        });
        await page.waitForNetworkIdle();
        await openReportCategory('Goals');
        await page.waitForNetworkIdle();

        // the real list scrolls, so the goals belonging to the newly selected site can sit below
        // the fold. Assert them in the DOM: that this reloaded is what the test is here to show.
        expect(await page.evaluate(function () {
            return $('.expandableList:visible .secondLevel:visible li').filter(function () {
                return $(this).text().indexOf('idSite 2') !== -1;
            }).length;
        })).to.be.above(0);

        await page.waitForTimeout(350); // wait for animation
        await page.mouse.move(0, 0); // move off the dropdown so no option keeps a stray :hover highlight
        expect(await screenshotPageWrapWithOpenList()).to.matchImage('alert_condition_reloaded_site2');
    });

    it('should reload alert conditions when site is changed back', async function () {
        await page.evaluate(function() {
            $('.siteSelector .piwikSelector__dropdown li:contains("Piwik test"):first').click();
        });
        await page.waitForNetworkIdle();
        await page.waitForNetworkIdle();

        // the counterpart to the assertion above: the other site's goals are gone. Checking that
        // options are still listed as well, so a list that simply closed cannot satisfy this.
        var options = await page.evaluate(function () {
            return $('.expandableList:visible .secondLevel:visible li').map(function () {
                return $(this).text().trim();
            }).get();
        });
        expect(options.length).to.be.above(0);
        expect(options.filter(function (option) {
            return option.indexOf('idSite 2') !== -1;
        })).to.have.lengthOf(0);

        await page.waitForTimeout(350); // wait for animation
        await page.mouse.move(0, 0); // move off the dropdown so no option keeps a stray :hover highlight
        expect(await screenshotPageWrapWithOpenList()).to.matchImage('alert_condition_reloaded_site1');
    });

    it('should save changed alert', async function () {
        // only check if name was changed in list, no need to make a screenshot
        await page.evaluate(function() {
            $('.expandableSelector .select-wrapper').click();
        });
        await page.type('#alertName', ' changed');
        // the field only passes the typed name on 50ms after the last key, and page.type waits just
        // those 50ms, so a slow runner could save the old name
        await page.waitForTimeout(250);
        // saving redirects to the list; waiting for that first, so the check below runs on the list
        await Promise.all([
            page.waitForNavigation(),
            page.click('.matomo-save-button'),
        ]);
        await page.waitForNetworkIdle();
        await page.waitForFunction('$(".pageWrap td:contains(\'Test Alert 1 changed\')").length > 0');
    });

    it('should show delete dialog', async function () {
        await page.click('tbody tr:first-child td button.deleteAlert');
        await page.waitForTimeout(350); // wait for animation
        var elem = await page.jQuery('.modal.open');
        expect(await elem.screenshot()).to.matchImage('delete');
    });

    it('should deleted alert', async function () {
        // only check if name isn't in list, no need to make a screenshot
        var confirm = await page.jQuery('.modal.open .modal-action:contains("Yes")');
        await Promise.all([
            page.waitForNavigation(),
            confirm.click(),
        ]);
        await page.waitForNetworkIdle();
        await page.waitForFunction('$(".pageWrap td:contains(\'Test Alert 1 changed\')").length == 0');
    });
});

